const categories=[{"full":"Алгоритмы, нейросети, ML, технологии искусственного интеллекта","short":"ИИ, нейросети и машинное обучение","count":7,"first":3},{"full":"Передача, обработка и хранение данных","short":"Передача и хранение данных","count":1,"first":11},{"full":"Облачные решения и сервис","short":"Облачные решения и сервисы","count":1,"first":13},{"full":"Информационная и кибербезопасность","short":"Информационная и кибербезопасность","count":1,"first":15},{"full":"Автоматизация процессов","short":"Автоматизация процессов","count":9,"first":17},{"full":"Информационные системы и ПО","short":"Информационные системы и ПО","count":1,"first":27},{"full":"Разработка сайтов и digital-продвижение","short":"Разработка сайтов и digital-продвижение","count":1,"first":29}];
const slides=[...document.querySelectorAll('.slide')];
const stage=document.getElementById('stage');let current=0;
const overlay=document.getElementById('modal-layer');
const detail=document.getElementById('modal-detail');
const index=document.getElementById('modal-index');
const qr=document.getElementById('modal-qr');
function fit(){stage.style.transform=`translate(-50%, -50%) scale(${Math.min(innerWidth/1600,innerHeight/900)})`}
window.addEventListener('resize',fit);fit();
function closeModal(){overlay.classList.remove('visible');detail.style.display='none';index.style.display='none';qr.style.display='none'}
function goTo(n){n=Math.max(0,Math.min(n,slides.length-1));slides[current].classList.remove('active');current=n;slides[current].classList.add('active');document.getElementById('count').textContent=`${String(n+1).padStart(2,'0')} / ${slides.length}`;document.getElementById('bar').style.width=`${Math.round((n+1)/slides.length*100)}%`;document.getElementById('back').disabled=n===0;document.getElementById('forth').disabled=n===slides.length-1;history.replaceState(null,'',`#${String(n+1).padStart(2,'0')}`);closeModal()}
function openModal(section){closeModal();overlay.classList.add('visible');section.style.display='flex';section.style.flexDirection='column'}
function esc(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function field(label,value,wide=false){if(!value)return '';return `<div class="${wide?'wide':''}"><div class="full-label">${esc(label)}</div><div class="full-data">${esc(value)}</div></div>`}
function showDetail(id){
 const s=DATA[id-1];
 document.getElementById('detail-kicker').textContent=`ПОЛНАЯ КАРТОЧКА · ${String(id).padStart(2,'0')}`;
 document.getElementById('detail-title').textContent=s.titleClean;
 document.getElementById('detail-body').innerHTML=`<div class="full-grid">${field('Компания',s.company)}${field('Направление',s.category)}${field('Описание',s.description,true)}${field('Клиент / отрасль',s.industry,true)}${field('Проблема',s.problem,true)}${field('Было',s.original.before)}${field('Стало',s.original.after)}${field('Решение',s.original.steps,true)}${field('Эффекты',s.original.effects,true)}${s.qr?`<div class="wide"><div class="full-label">КОНТАКТ</div><button style="border:0;background:transparent;padding:0" type="button" onclick="showQR(${id})"><img class="modal-qr" src="${QRS[s.qr]}" alt="QR-код для связи"></button></div>`:''}</div>`;
 openModal(detail);
}
function showQR(id){const s=DATA[id-1];if(!s.qr)return;document.getElementById('qr-image').src=QRS[s.qr];document.getElementById('qr-name').textContent=s.company;openModal(qr)}
function showIndex(){let entries='';categories.forEach((c,j)=>{entries+=`<div class="menu-category">${String(j+1).padStart(2,'0')} / ${esc(c.short)}</div>`;DATA.filter(s=>s.category.trim()===c.full).forEach(s=>{entries+=`<button class="menu-entry" type="button" onclick="goTo(${s.slideIndex})"><span>${String(s.id).padStart(2,'0')}</span>${esc(s.titleClean)}</button>`})});document.getElementById('index-body').innerHTML=entries;openModal(index)}
document.getElementById('back').onclick=()=>goTo(current-1);document.getElementById('forth').onclick=()=>goTo(current+1);document.getElementById('index-open').onclick=showIndex;document.getElementById('screen').onclick=()=>document.fullscreenElement?document.exitFullscreen():document.documentElement.requestFullscreen();document.querySelectorAll('.modal-close').forEach(b=>b.onclick=closeModal);overlay.addEventListener('click',e=>{if(e.target===overlay)closeModal()});document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeModal();return}if(overlay.classList.contains('visible'))return;if(e.key==='ArrowRight'||e.key==='PageDown'||e.key===' '){e.preventDefault();goTo(current+1)}if(e.key==='ArrowLeft'||e.key==='PageUp'){e.preventDefault();goTo(current-1)}if(e.key==='Home')goTo(0);if(e.key==='End')goTo(slides.length-1);if(e.key.toLowerCase()==='f'&&!e.metaKey)document.getElementById('screen').click();if(e.key.toLowerCase()==='m'&&!e.metaKey)showIndex()});
const hash=location.hash.match(/^#(\d+)$/);goTo(hash?Number(hash[1])-1:0);

// PDF binary is embedded below for a standalone HTML presentation.
function downloadEmbeddedPdf(ev) {
  if (ev) ev.preventDefault();
  const source=document.getElementById('embedded-pdf');
  if(!source || !source.textContent.trim()){alert('PDF ещё не встроен в этот файл.');return false;}
  try {
    const base64=source.textContent.trim();
    const blocks=[];
    for(let i=0;i<base64.length;i+=32768) {
      const piece=atob(base64.slice(i,i+32768));
      const bytes=new Uint8Array(piece.length);
      for(let j=0;j<piece.length;j++)bytes[j]=piece.charCodeAt(j);
      blocks.push(bytes);
    }
    const blob=new Blob(blocks,{type:'application/pdf'});
    const objectURL=URL.createObjectURL(blob);
    const a=document.createElement('a');
    a.href=objectURL;
    a.download='ИТЭРА_Каталог_DataPool_QR_исправлены.pdf';
    document.body.appendChild(a);a.click();a.remove();
    setTimeout(()=>URL.revokeObjectURL(objectURL),20000);
  } catch(err){console.error('PDF download error:',err);alert('Не получилось скачать PDF.');}
  return false;
}
function openDpQR(){document.getElementById('dp-qr-modal').hidden=false;}
function closeDpQR(){document.getElementById('dp-qr-modal').hidden=true;}
document.getElementById('dp-qr-modal').addEventListener('click',function(e){if(e.target===this)closeDpQR()});
document.addEventListener('keydown',function(e){if(e.key==='Escape')closeDpQR()});